floor_fn:
"""
  >>> dr_evil(10)
  '10 dollars'
  >>> dr_evil(1000000)
  '1000000 dollars (pinky)'
  >>> dr_evil(2000000)
  '2000000 dollars (pinky)'
  """
def dr_evil(amount: Any) -> object {
    if (amount >= 1000000) {
        return f"{amount} dollars (pinky)";
    } else {
        return f"{amount} dollars";
    }
}

